// Optional overrides via webhook body: { "category": "...", "product_count": 10 }
const body = ($json && $json.body) ? $json.body : {};

const categories = [
  "wireless earbuds",
  "robot vacuums",
  "air fryers",
  "gaming laptops",
  "standing desks",
  "smart watches",
  "coffee makers",
  "electric bikes",
  "4k monitors",
  "mechanical keyboards",
  "portable power stations",
  "smart home security cameras",
  "noise cancelling headphones",
  "ergonomic office chairs"
];

// Rotate deterministically by day-of-year so repeated daily runs sweep the
// whole category list over time instead of hammering the same category.
const now = new Date();
const startOfYear = new Date(Date.UTC(now.getUTCFullYear(), 0, 0));
const dayOfYear = Math.floor((now - startOfYear) / 86400000);
const rotatedCategory = categories[dayOfYear % categories.length];

const countries = ["US", "GB", "CA", "AU"];
const review_styles = ["in_depth_review", "buyers_guide", "comparison", "budget_pick"];

return [{
  json: {
    category: body.category || rotatedCategory,
    product_count: body.product_count || 10,
    countries,
    review_styles,
    ollama_base_url: "https://api.deepseek.com/v1",
    research_model: "deepseek-flash"
  }
}];

const cfg = $('Config').item.json;
const category = cfg.category;

const queries = [
  `most popular ${category} 2026`,
  `best selling ${category}`,
  `top ${category} to buy right now`,
  `${category} buying guide reviews`
];

const seen = new Map();
for (const q of queries) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: 'http://searxng:8080/search',
      qs: { format: 'json', language: 'en', q },
      json: true
    });
    for (const r of (res.results || []).slice(0, 12)) {
      if (!seen.has(r.url)) {
        seen.set(r.url, { title: r.title, url: r.url, content: (r.content || '').slice(0, 400) });
      }
    }
  } catch (e) {
    // one query failing shouldn't kill discovery - just yields fewer candidates
  }
}

return [{
  json: {
    ...cfg,
    candidate_pages: Array.from(seen.values())
  }
}];

const cfg = $input.item.json;

const existingRows = $('Get Existing Product Keys').all().map(i => i.json);
const existingNames = existingRows.map(r => r.normalized_name).filter(Boolean);

const system_prompt = `You are a product research assistant compiling a shortlist of real, currently popular, currently-sold products for an affiliate review site.

You will be given real web search results (title/url/snippet) about a product category.

Rules:
1. Extract ONLY real products that are actually named/mentioned in the given search results - never invent a product.
2. Favour products that appear to be genuinely POPULAR / best-selling / frequently recommended across the given results, not obscure ones mentioned only once.
3. Return exactly ${cfg.product_count} products if that many distinct real products appear in the results; if fewer genuinely distinct products are mentioned, return as many as you can find (never pad with duplicates or invented items).
4. Each product must be a specific, buyable model (brand + model name), not a generic category description.
5. Products must be UNIQUE - do not list the same base model twice (e.g. two colour variants of the same model count as ONE product; pick the more prominently mentioned one).
6. Do NOT return any product whose name closely matches one of these ALREADY-QUEUED products (case-insensitive, ignore punctuation): ${JSON.stringify(existingNames)}
7. For each product, pick a source_url that is EXACTLY one of the URLs given to you below (copy it verbatim) - never invent or modify a URL. Prefer a URL whose page is actually about that specific product.
8. Include your best guess at the brand name for each product, extracted from the text given.
9. Output JSON only, matching the schema.`;

const user_prompt = `CATEGORY: ${cfg.category}

SEARCH RESULTS:
${JSON.stringify(cfg.candidate_pages)}

Compile the shortlist of the most POPULAR distinct real products now.`;

const discovery_schema = {
  type: "object",
  properties: {
    products: {
      type: "array",
      items: {
        type: "object",
        properties: {
          product_name: { type: "string" },
          brand: { type: "string" },
          source_url: { type: "string" }
        },
        required: ["product_name", "brand", "source_url"]
      }
    }
  },
  required: ["products"]
};

return [{
  json: {
    ...cfg,
    discovery_system_prompt: system_prompt + `\n\nReturn ONLY a JSON object matching exactly this schema - no markdown fences, no extra commentary:\n${JSON.stringify(discovery_schema)}`,
    discovery_user_prompt: user_prompt,
    discovery_schema
  }
}];

const res = $input.item.json;
const raw = (res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) || (res.message && res.message.content) || res.response || '';

let parsed = null, parseError = null;
try { parsed = JSON.parse(raw); } catch (e) { parseError = e.message; }

const cfg = $('Config').item.json;
const candidateUrls = new Set(($('Search Category Candidates').item.json.candidate_pages || []).map(p => p.url));
const existingNames = new Set($('Get Existing Product Keys').all().map(i => i.json.normalized_name).filter(Boolean));

function normalize(s) {
  return (s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}
function slugify(s) {
  return (s || '').toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

let products = (parsed && Array.isArray(parsed.products)) ? parsed.products : [];

const seenNames = new Set();
const deduped = [];
for (const p of products) {
  if (!p.product_name) continue;
  const norm = normalize(`${p.brand || ''} ${p.product_name}`);
  if (seenNames.has(norm)) continue;
  if (existingNames.has(norm)) continue; // already queued on a previous run
  // Only trust source URLs that were actually in the real search results - never a model-invented URL.
  if (!p.source_url || !candidateUrls.has(p.source_url)) continue;
  seenNames.add(norm);
  deduped.push({
    product_name: p.product_name,
    brand: p.brand || '',
    category: cfg.category,
    source_url: p.source_url
  });
  if (deduped.length >= cfg.product_count) break;
}

if (deduped.length === 0) {
  return [{ json: { _hasProducts: false, _discoveryError: `No usable NEW products extracted (parseError=${parseError || 'none'})`, product_name: null } }];
}

// Assign country_code / review_style by rotation so the queue spreads across
// markets and formats instead of every product landing on the same combo.
return deduped.map((p, idx) => {
  const country_code = cfg.countries[idx % cfg.countries.length];
  const review_style = cfg.review_styles[idx % cfg.review_styles.length];
  const product_key = slugify(`${p.brand}-${p.product_name}-${country_code}`);
  return {
    json: {
      ...p,
      _hasProducts: true,
      country_code,
      review_style,
      product_key,
      discovery_meta: {
        discovered_via: 'stage3a-discover-and-queue',
        source_url: p.source_url
      }
    }
  };
});

const item = $input.item.json;
const sourceUrl = item.source_url;

// Discovery's source_url is only guaranteed to be a REAL search result for this
// product - not necessarily the brand's own site (confirmed live: a real run's
// source_url for "Sony WH-1000XM6" was rtings.com's "best noise-cancelling
// headphones" roundup page, whose og:image is that roundup's own listicle
// graphic, not a Sony product photo). Scraping still runs against whatever page
// discovery found, but the result is only trusted/kept as a manufacturer photo
// when the page's own hostname plausibly belongs to the brand - an unrelated
// site's thumbnail mislabeled as "manufacturer" would be worse than no photo at
// all (Stage 3b's Openverse fallback handles that case instead).
function hostnameOf(url) {
  try { const m = String(url).match(/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\/(?:[^@/]+@)?([^/:?#]+)/); return m ? m[1].toLowerCase().replace(/^www\./, '') : ''; } catch (e) { return ''; }
}
function looksLikeBrandDomain(url, brand) {
  if (!brand) return false;
  const host = hostnameOf(url).replace(/[^a-z0-9]/g, '');
  const normalizedBrand = String(brand).toLowerCase().replace(/[^a-z0-9]/g, '');
  return !!normalizedBrand && host.includes(normalizedBrand);
}

// n8n's Code node sandbox has no global URL constructor (confirmed the hard way
// elsewhere in this pipeline - see hostnameOf() in Validate Research Trust), so
// relative image URLs are resolved by hand instead of new URL(url, base).
function resolveUrl(url, base) {
  if (!url) return null;
  url = String(url).trim();
  if (/^https?:\/\//i.test(url)) return url;
  const schemeMatch = String(base).match(/^([a-zA-Z][a-zA-Z0-9+.-]*:)/);
  const scheme = schemeMatch ? schemeMatch[1] : 'https:';
  if (/^\/\//.test(url)) return scheme + url;
  const originMatch = String(base).match(/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\/[^/]+/);
  const origin = originMatch ? originMatch[0] : '';
  if (url.startsWith('/')) return origin + url;
  const basePath = String(base).replace(/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\/[^/]+/, '').replace(/[^/]*$/, '');
  return origin + basePath + url;
}

let productImages = [];

// Finds the manufacturer's own product photos by scraping the real source_url
// page that discovery already verified against actual search results - og:image /
// twitter:image / JSON-LD Product.image are the same tags manufacturer sites set
// for their own link-preview cards, so this is a deterministic, no-extra-API-key
// way to get precise product photography instead of Openverse's generic stock
// search (kept as Stage 3b's fallback when this finds nothing).
//
// Not fatal on failure - an unreachable/blocking page just leaves product_images
// empty and Stage 3b falls back to Openverse, same as today.
try {
  if (sourceUrl && looksLikeBrandDomain(sourceUrl, item.brand)) {
    const html = await this.helpers.httpRequest({
      method: 'GET',
      url: sourceUrl,
      headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36' },
      timeout: 20000
    });
    const htmlStr = String(html);
    const seen = new Set();

    function addImage(url, tag) {
      const resolved = resolveUrl(url, sourceUrl);
      if (!resolved || !/^https?:\/\//i.test(resolved) || seen.has(resolved)) return;
      // A manufacturer's own og:image/twitter:image is often a generic sitewide
      // social-share fallback (brand wordmark/icon), not a photo of the specific
      // product being reviewed - confirmed live: samsung.com's product page's
      // twitter:image was literally "logo-square-letter.png", the plain Samsung
      // logo, which then outranked several genuinely good product photos from
      // editorial sources since manufacturer_scrape is checked first. Filename
      // pattern is a blunt but effective filter for this specific failure mode.
      if (/logo|favicon|icon[-_.]|sprite|brand-?mark|placeholder|og-?default|default-?share/i.test(resolved)) return;
      seen.add(resolved);
      productImages.push({ url: resolved, source: 'manufacturer_scrape', tag, is_primary: productImages.length === 0 });
    }

    const metaTags = htmlStr.match(/<meta\b[^>]*>/gi) || [];
    for (const tag of metaTags) {
      const propMatch = tag.match(/(?:property|name)\s*=\s*["']([^"']+)["']/i);
      const contentMatch = tag.match(/content\s*=\s*["']([^"']+)["']/i);
      if (!propMatch || !contentMatch) continue;
      const prop = propMatch[1].toLowerCase();
      if (['og:image', 'og:image:secure_url', 'og:image:url', 'twitter:image', 'twitter:image:src'].includes(prop)) {
        addImage(contentMatch[1], prop);
      }
    }

    const ldBlocks = htmlStr.match(/<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi) || [];
    for (const block of ldBlocks) {
      const inner = block.replace(/^<script[^>]*>/i, '').replace(/<\/script>$/i, '');
      try {
        const data = JSON.parse(inner.trim());
        const nodes = Array.isArray(data) ? data : (data['@graph'] || [data]);
        for (const node of nodes) {
          if (!node || typeof node !== 'object') continue;
          const type = String(node['@type'] || '').toLowerCase();
          if (type.includes('product') && node.image) {
            const imgs = Array.isArray(node.image) ? node.image : [node.image];
            for (const img of imgs) addImage(typeof img === 'string' ? img : (img && img.url), 'jsonld:product');
          }
        }
      } catch (e) { /* not parseable JSON-LD, skip this block */ }
    }

    productImages = productImages.slice(0, 5);
  }
} catch (e) {
  productImages = [];
}

return [{ json: { ...item, product_images: productImages } }];

const parsed = $('Parse Discovery JSON').all();
const hasError = parsed.length === 1 && parsed[0].json._discoveryError;
const attempted = hasError ? 0 : parsed.length;

let inserted = 0;
try { inserted = $('Insert Into Queue').all().filter(i => i.json && i.json.id).length; } catch (e) { inserted = 0; }

return [{
  json: {
    category: $('Config').first().json.category,
    attempted,
    inserted,
    skipped_as_duplicate: attempted - inserted,
    discovery_error: hasError ? parsed[0].json._discoveryError : null,
    ran_at: new Date().toISOString()
  }
}];
